\set ON_ERROR_STOP on
begin;
create schema test;
create function test.ok(condition boolean,label text) returns void language plpgsql as $$begin if condition is distinct from true then raise exception 'FAILED: %',label;end if;raise notice 'PASS: %',label;end$$;
insert into auth.users(id) values('00000000-0000-4000-8000-000000000901');
insert into staff_profiles(id,email,name,role) values('00000000-0000-4000-8000-000000000901','admin@avrasyaproperties.com','Isolated owner','admin');
insert into auth.sessions(id,user_id,created_at) values('00000000-0000-4000-8000-000000000902','00000000-0000-4000-8000-000000000901',now()-interval '1 hour');
select test.ok(public.admin_login_begin('unknown@example.test',gen_random_uuid())->>'unknown'='true','Unknown accounts never create counters');
select test.ok(public.admin_login_begin(' ADMIN@AVRASYAPROPERTIES.COM ','00000000-0000-4000-8000-000000000911')->>'user_id'='00000000-0000-4000-8000-000000000901','Email is normalized');
select test.ok(public.admin_login_begin('admin@avrasyaproperties.com',gen_random_uuid())->>'busy'='true','Concurrent login cannot race the counter');
select public.admin_login_finish('00000000-0000-4000-8000-000000000901','00000000-0000-4000-8000-000000000911',false);
select public.admin_login_begin('admin@avrasyaproperties.com','00000000-0000-4000-8000-000000000912');
select public.admin_login_finish('00000000-0000-4000-8000-000000000901','00000000-0000-4000-8000-000000000912',null);
select test.ok((select failures=1 from private.admin_login_state),'Service outages do not reset or increase failures');
select public.admin_login_begin('admin@avrasyaproperties.com','00000000-0000-4000-8000-000000000913');
select public.admin_login_finish('00000000-0000-4000-8000-000000000901','00000000-0000-4000-8000-000000000913',false);
select public.admin_login_begin('admin@avrasyaproperties.com','00000000-0000-4000-8000-000000000914');
select public.admin_login_finish('00000000-0000-4000-8000-000000000901','00000000-0000-4000-8000-000000000914',false);
select test.ok((select failures=3 and blocked_until=now()+interval '15 minutes' from private.admin_login_state),'Third failure imposes exactly 15 minute block');
select test.ok((select count(*)=1 and bool_and(recipient='info.avrasyaproperties@gmail.com') from private.admin_security_mail),'One alert targets the specified Gmail mailbox');
select test.ok(public.admin_login_begin('admin@avrasyaproperties.com',gen_random_uuid())->>'blocked_until' is not null,'Even correct credentials cannot start another gateway attempt');
select test.ok(public.admin_password_verification('{"user_id":"00000000-0000-4000-8000-000000000901","valid":true}')->>'decision'='reject','Native hook rejects password login during block');
select test.ok(public.admin_password_verification('{"user_id":"00000000-0000-4000-8000-000000000901","valid":true}')->>'should_logout_user'='false','Attackers cannot terminate existing work through login failures');
insert into auth.sessions(id,user_id,created_at) values('00000000-0000-4000-8000-000000000903','00000000-0000-4000-8000-000000000901',now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000901","session_id":"00000000-0000-4000-8000-000000000902"}',true);
reset role;
select test.ok(private.staff_role()='admin','Session created before the block remains usable');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000901","session_id":"00000000-0000-4000-8000-000000000903"}',true);
select test.ok(private.staff_role() is null,'Fresh direct Auth sessions cannot bypass admin data block');
select test.ok(not has_function_privilege('anon','public.admin_login_finish(uuid,uuid,boolean)','execute'),'Anonymous callers cannot forge password verification');
select test.ok(not has_function_privilege('authenticated','public.admin_recovery_finish(uuid)','execute'),'Staff cannot clear blocks using a direct RPC');
select test.ok(not has_function_privilege('authenticated','public.admin_password_verification(jsonb)','execute'),'Native hook cannot be forged by a browser');
select public.admin_recovery_finish('00000000-0000-4000-8000-000000000901');
select test.ok(private.staff_role()='admin','Verified password recovery clears block');
select test.ok(public.admin_recovery_begin('admin@avrasyaproperties.com')->>'recipient'='info.avrasyaproperties@gmail.com','Recovery goes to secondary mailbox without changing account identity');
select test.ok(public.admin_recovery_begin('admin@avrasyaproperties.com')->>'throttled'='true','Recovery requests are rate limited');
select public.admin_mail_claim();
select test.ok(public.admin_mail_claim()='[]'::jsonb,'Alert worker claims cannot duplicate concurrent delivery');
select public.admin_mail_finish(id,'isolated-provider-id',null) from private.admin_security_mail;
select test.ok(public.admin_mail_claim()='[]'::jsonb,'Accepted alerts are not delivered again');
select public.admin_password_verification('{"user_id":"00000000-0000-4000-8000-000000000901","valid":false}');
select test.ok((select failures=1 from private.admin_login_state),'Native hook records a direct failed Auth attempt');
select public.admin_login_begin('admin@avrasyaproperties.com','00000000-0000-4000-8000-000000000915');
select public.admin_password_verification('{"user_id":"00000000-0000-4000-8000-000000000901","valid":false}');
select test.ok((select failures=1 from private.admin_login_state),'Native hook and gateway do not double count');
select public.admin_login_finish('00000000-0000-4000-8000-000000000901','00000000-0000-4000-8000-000000000915',true);
select test.ok((select failures=0 from private.admin_login_state),'Successful sign-in resets the consecutive failure count');
update private.admin_login_state set failures=3,locked_at=now()-interval '16 minutes',blocked_until=now()-interval '1 minute';
select test.ok(public.admin_login_begin('admin@avrasyaproperties.com',gen_random_uuid())->>'user_id' is not null,'Block automatically expires after 15 minutes');
select test.ok(public.admin_mail_worker_valid((select credential from private.admin_security_worker)),'Private generated worker credential is accepted');
select test.ok(not public.admin_mail_worker_valid(repeat('x',72)),'Forged worker credential is rejected');
select test.ok(not has_table_privilege('authenticated','private.admin_security_worker','select'),'Browser cannot read the worker credential');
rollback;
